Here's a C implementation of a simple arena allocator with alignment support using only standard library functions:

```c
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Arena structure
typedef struct {
    void *buffer;           // Main memory buffer
    size_t capacity;        // Total capacity in bytes
    size_t offset;          // Current offset within the buffer
    size_t alignment;       // Alignment requirement in bytes
} Arena;

// Helper function to align an offset to the given alignment
static size_t align_offset(size_t offset, size_t alignment) {
    size_t mask = alignment - 1;
    return (offset + mask) & ~mask;
}

// Helper function to align a pointer to the given alignment
static void *align_pointer(void *ptr, size_t alignment) {
    uintptr_t address = (uintptr_t)ptr;
    uintptr_t mask = alignment - 1;
    return (void *)((address + mask) & ~mask);
}

// Create a new arena with specified capacity
Arena* arena_create(size_t capacity, size_t alignment) {
    if (capacity == 0 || alignment == 0 || (alignment & (alignment - 1)) != 0) {
        return NULL; // Invalid parameters or alignment not power of 2
    }

    // Allocate arena structure
    Arena *arena = (Arena *)malloc(sizeof(Arena));
    if (arena == NULL) {
        return NULL;
    }

    // Allocate buffer with extra space for alignment
    void *buffer = malloc(capacity + alignment);
    if (buffer == NULL) {
        free(arena);
        return NULL;
    }

    arena->buffer = buffer;
    arena->capacity = capacity;
    arena->offset = 0;
    arena->alignment = alignment;

    return arena;
}

// Allocate memory from the arena with alignment
void* arena_alloc(Arena *arena, size_t size) {
    if (arena == NULL || size == 0) {
        return NULL;
    }

    // Calculate aligned offset
    size_t aligned_offset = align_offset(arena->offset, arena->alignment);

    // Check if we have enough space
    if (aligned_offset + size > arena->capacity) {
        return NULL; // Not enough space
    }

    // Get the aligned pointer
    void *aligned_ptr = (char *)arena->buffer + aligned_offset;

    // Update offset (include any padding for alignment)
    arena->offset = aligned_offset + size;

    return aligned_ptr;
}

// Allocate zero-initialized memory from the arena with alignment
void* arena_calloc(Arena *arena, size_t count, size_t size) {
    size_t total_size = count * size;
    if (count != 0 && total_size / count != size) {
        return NULL; // Overflow check
    }

    void *ptr = arena_alloc(arena, total_size);
    if (ptr != NULL) {
        memset(ptr, 0, total_size);
    }

    return ptr;
}

// Reset the arena (free all allocations but keep the buffer)
void arena_reset(Arena *arena) {
    if (arena != NULL) {
        arena->offset = 0;
    }
}

// Destroy the arena and free all memory
void arena_destroy(Arena *arena) {
    if (arena != NULL) {
        free(arena->buffer);
        free(arena);
    }
}

// Example usage and test
#ifdef ARENA_TEST
#include <stdio.h>

int main() {
    // Create arena with 1024 bytes capacity and 16-byte alignment
    Arena *arena = arena_create(1024, 16);
    if (arena == NULL) {
        printf("Failed to create arena\n");
        return 1;
    }

    // Test 1: Basic allocation
    printf("Test 1: Basic allocation\n");
    int *a = arena_alloc(arena, sizeof(int));
    if (a != NULL) {
        *a = 42;
        printf("a = %d (address: %p, aligned to %lu)\n", *a, (void*)a, arena->alignment);
    }

    // Test 2: Allocation with different alignment requirements
    printf("\nTest 2: Aligned allocations\n");
    double *b = arena_alloc(arena, sizeof(double));
    if (b != NULL) {
        *b = 3.14159;
        printf("b = %f (address: %p, aligned to %lu)\n", *b, (void*)b, arena->alignment);
    }

    // Test 3: Multiple allocations
    printf("\nTest 3: Multiple allocations\n");
    char *strings[3];
    for (int i = 0; i < 3; i++) {
        strings[i] = arena_alloc(arena, 32);
        if (strings[i] != NULL) {
            sprintf(strings[i], "String %d", i);
            printf("strings[%d] = '%s' (address: %p)\n", i, strings[i], (void*)strings[i]);
        }
    }

    // Test 4: Check alignment
    printf("\nTest 4: Alignment verification\n");
    void *ptr1 = arena_alloc(arena, 1);
    void *ptr2 = arena_alloc(arena, 1);
    void *ptr3 = arena_alloc(arena, 1);
    if (ptr1 && ptr2 && ptr3) {
        printf("ptr1: %p (offset: %lu)\n", ptr1, (char*)ptr1 - (char*)arena->buffer);
        printf("ptr2: %p (offset: %lu)\n", ptr2, (char*)ptr2 - (char*)arena->buffer);
        printf("ptr3: %p (offset: %lu)\n", ptr3, (char*)ptr3 - (char*)arena->buffer);
    }

    // Test 5: Reset arena
    printf("\nTest 5: Arena reset\n");
    printf("Before reset - offset: %lu\n", arena->offset);
    arena_reset(arena);
    printf("After reset - offset: %lu\n", arena->offset);

    // Test 6: Allocate again after reset
    printf("\nTest 6: Allocation after reset\n");
    int *c = arena_alloc(arena, sizeof(int));
    if (c != NULL) {
        *c = 100;
        printf("c = %d (address: %p)\n", *c, (void*)c);
    }

    // Test 7: Zero-initialized allocation
    printf("\nTest 7: Zero-initialized allocation\n");
    int *d = arena_calloc(arena, 5, sizeof(int));
    if (d != NULL) {
        printf("d[0..4] = ");
        for (int i = 0; i < 5; i++) {
            printf("%d ", d[i]);
        }
        printf("(address: %p)\n", (void*)d);
    }

    // Destroy the arena
    arena_destroy(arena);

    return 0;
}
#endif
```

## Key Features:

1. **Memory Management**:
   - `arena_create(capacity, alignment)`: Creates an arena with specified capacity and alignment requirement
   - `arena_alloc(arena, size)`: Allocates memory with proper alignment
   - `arena_calloc(arena, count, size)`: Allocates zero-initialized memory (bonus function)
   - `arena_reset(arena)`: Resets the arena without freeing memory
   - `arena_destroy(arena)`: Frees all memory including the arena structure

2. **Alignment Support**:
   - Alignment must be a power of 2
   - Uses bitwise operations for efficient alignment calculation
   - Guarantees returned pointers meet the alignment requirement

3. **Safety Features**:
   - Validates parameters (alignment power of 2, non-zero capacity)
   - Checks for allocation failures
   - Overflow protection in `arena_calloc`
   - Handles NULL pointers gracefully

4. **Implementation Details**:
   - Uses integer arithmetic for alignment: `(offset + mask) & ~mask`
   - Allocates extra bytes for alignment padding
   - Simple O(1) allocation with just a pointer increment
   - No fragmentation (linear allocation only)

## Usage:

To compile and test:
```bash
gcc -DARENA_TEST -o arena arena.c
./arena
```

The test mode demonstrates all features including allocation, alignment, reset, and zero-initialization.

Here's a C function that multiplies a matrix by a vector with cache-friendly optimization:

```c
#include <stdio.h>

#define N 1024  // Matrix dimension (N x N matrix, N-length vector)

void matvec(float A[N][N], float x[N], float y[N])
{
    // Zero out the result vector
    for (int i = 0; i < N; i++)
        y[i] = 0.0f;

    /*
     * Cache-friendly loop order: rows first, then columns.
     * 
     * Why this order works well:
     * 
     * 1. Row-major storage: In C, matrices are stored in row-major order, meaning
     *    consecutive elements in a row are adjacent in memory.
     *    A[0][0], A[0][1], ..., A[0][N-1] are contiguous.
     * 
     * 2. Spatial locality: By iterating through columns in the inner loop,
     *    we access A[i][0], A[i][1], A[i][2], etc., sequentially.
     *    This allows the CPU's cache line prefetcher to load nearby elements
     *    before we need them.
     * 
     * 3. Temporal locality: We reuse vector x[j] for all rows i.
     *    Once x[j] is loaded into cache for one row, it remains available
     *    for subsequent rows (if it fits in cache).
     * 
     * 4. Good memory access pattern: For each row i, we:
     *    - Access one contiguous block of matrix A (row i)
     *    - Access the same vector x (but likely already cached after first few rows)
     *    - Write one element to result vector y (contiguous writes)
     * 
     * Alternative loop order (i→j→k) would cause poor cache performance:
     * A[0][0], A[1][0], A[2][0], ... would jump by entire row sizes,
     * causing many cache misses.
     */

    for (int i = 0; i < N; i++)      // For each row in matrix
    {
        float sum = 0.0f;
        for (int j = 0; j < N; j++)  // For each column in that row
        {
            // Access pattern:
            // A[i][j]: sequential along row (spatial locality)
            // x[j]: sequential along vector (spatial locality)
            sum += A[i][j] * x[j];
        }
        y[i] = sum;  // Write result for row i
    }

    /*
     * Advanced optimization notes:
     * 
     * For even better performance, you could:
     * 1. Use loop unrolling (process 4 elements at a time)
     * 2. Use SIMD intrinsics for vector operations
     * 3. Implement cache blocking (tiling) for very large matrices
     * 4. Align memory to cache line boundaries (64 bytes typically)
     */
}

// Example usage and test
int main()
{
    float A[N][N], x[N], y[N];

    // Initialize with some values (for demonstration)
    for (int i = 0; i < N; i++)
    {
        x[i] = 1.0f;  // Vector of ones
        for (int j = 0; j < N; j++)
            A[i][j] = 1.0f;  // Matrix of ones
    }

    matvec(A, x, y);

    // Verify: should get N for each element (sum of N ones)
    printf("First few results: %.1f, %.1f, %.1f\n", y[0], y[1], y[2]);
    printf("Expected: %d.0 for each\n", N);

    return 0;
}
```

## Key Cache-Friendly Features Explained:

1. **Row-Major Access Pattern**: Since C stores matrices row-major, `A[i][j]` accesses memory sequentially when `j` varies, hitting adjacent cache lines.

2. **Temporal Reuse of Vector**: The vector `x` is read in the same order for every row. Once it's loaded into cache for the first few rows, it stays cached for subsequent rows (assuming N isn't huge).

3. **Simple Linear Access**: No jumping around memory - everything flows sequentially through memory.

4. **Minimal Cache Thrashing**: The loop order ensures we don't need to constantly reload data from main memory.

## For Very Large Matrices (N > cache size):

For matrices too large to fit in cache, you'd need **cache blocking** (tiling), which processes the matrix in small blocks that fit in L1 cache. But for most practical cases, the simple row-first loop order is excellent.

# C Thread Pool with Pthreads

Here's a complete thread pool skeleton with fixed workers, task queue, mutex/cond synchronization, task submission, and graceful shutdown:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <stdbool.h>

/* ======================== DATA STRUCTURES ======================== */

// Task structure: function pointer + argument
typedef struct task {
    void (*function)(void*);    // Task function
    void* arg;                  // Argument to pass
    struct task* next;          // For linked list queue
} task_t;

// Thread pool structure
typedef struct {
    pthread_t* workers;         // Array of worker threads
    int num_workers;            // Number of worker threads

    task_t* task_head;          // Front of task queue
    task_t* task_tail;          // Rear of task queue
    int task_count;             // Current number of tasks in queue

    pthread_mutex_t mutex;      // Mutex for task queue
    pthread_cond_t not_empty;   // Condition: queue has tasks
    pthread_cond_t all_done;    // Condition: all tasks completed (for shutdown)

    bool shutdown;              // Shutdown flag
    bool waiting;               // Are we in shutdown waiting state?
} thread_pool_t;

/* ======================== WORKER THREAD FUNCTION ======================== */

void* worker_thread(void* arg) {
    thread_pool_t* pool = (thread_pool_t*)arg;

    while (1) {
        // Lock mutex to access queue
        pthread_mutex_lock(&pool->mutex);

        // Wait while queue is empty AND not shutting down
        while (pool->task_head == NULL && !pool->shutdown) {
            pthread_cond_wait(&pool->not_empty, &pool->mutex);
        }

        // If shutdown requested AND no tasks remain, exit
        if (pool->shutdown && pool->task_count == 0) {
            break;
        }

        // Get task from queue (dequeue from head)
        task_t* current_task = pool->task_head;
        pool->task_head = current_task->next;

        if (pool->task_head == NULL) {
            pool->task_tail = NULL;
        }

        pool->task_count--;

        // If we were waiting and now no tasks left, signal all_done
        if (pool->waiting && pool->task_count == 0) {
            pthread_cond_signal(&pool->all_done);
        }

        // Unlock mutex before executing task
        pthread_mutex_unlock(&pool->mutex);

        // Execute the task
        current_task->function(current_task->arg);

        // Free the task structure
        free(current_task);
    }

    // Unlock mutex if breaking from loop (shutdown case)
    pthread_mutex_unlock(&pool->mutex);

    return NULL;
}

/* ======================== POOL MANAGEMENT FUNCTIONS ======================== */

// Create a new thread pool
thread_pool_t* thread_pool_create(int num_workers) {
    thread_pool_t* pool = malloc(sizeof(thread_pool_t));
    if (!pool) {
        return NULL;
    }

    // Initialize pool
    pool->num_workers = num_workers;
    pool->task_head = NULL;
    pool->task_tail = NULL;
    pool->task_count = 0;
    pool->shutdown = false;
    pool->waiting = false;

    // Initialize mutex and condition variables
    if (pthread_mutex_init(&pool->mutex, NULL) != 0 ||
        pthread_cond_init(&pool->not_empty, NULL) != 0 ||
        pthread_cond_init(&pool->all_done, NULL) != 0) {
        free(pool);
        return NULL;
    }

    // Create worker threads
    pool->workers = malloc(num_workers * sizeof(pthread_t));
    if (!pool->workers) {
        pthread_mutex_destroy(&pool->mutex);
        pthread_cond_destroy(&pool->not_empty);
        pthread_cond_destroy(&pool->all_done);
        free(pool);
        return NULL;
    }

    for (int i = 0; i < num_workers; i++) {
        if (pthread_create(&pool->workers[i], NULL, worker_thread, pool) != 0) {
            // Cleanup on failure
            for (int j = 0; j < i; j++) {
                pthread_cancel(pool->workers[j]);
                pthread_join(pool->workers[j], NULL);
            }
            free(pool->workers);
            pthread_mutex_destroy(&pool->mutex);
            pthread_cond_destroy(&pool->not_empty);
            pthread_cond_destroy(&pool->all_done);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

// Submit a task to the thread pool
bool thread_pool_submit(thread_pool_t* pool, void (*function)(void*), void* arg) {
    if (!pool || !function) {
        return false;
    }

    // Create new task
    task_t* new_task = malloc(sizeof(task_t));
    if (!new_task) {
        return false;
    }

    new_task->function = function;
    new_task->arg = arg;
    new_task->next = NULL;

    // Lock mutex to add to queue
    pthread_mutex_lock(&pool->mutex);

    if (pool->shutdown) {
        pthread_mutex_unlock(&pool->mutex);
        free(new_task);
        return false;
    }

    // Add task to queue (enqueue to tail)
    if (pool->task_tail == NULL) {
        pool->task_head = new_task;
        pool->task_tail = new_task;
    } else {
        pool->task_tail->next = new_task;
        pool->task_tail = new_task;
    }

    pool->task_count++;

    // Signal that queue is not empty
    pthread_cond_signal(&pool->not_empty);

    pthread_mutex_unlock(&pool->mutex);
    return true;
}

// Shutdown the thread pool
// If wait=true, wait for all queued tasks to complete first
void thread_pool_shutdown(thread_pool_t* pool, bool wait) {
    if (!pool) {
        return;
    }

    pthread_mutex_lock(&pool->mutex);

    if (pool->shutdown) {
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    pool->shutdown = true;

    if (wait) {
        pool->waiting = true;
        // Wait for all tasks to complete
        while (pool->task_count > 0) {
            pthread_cond_wait(&pool->all_done, &pool->mutex);
        }
    }

    // Wake up all waiting workers
    pthread_cond_broadcast(&pool->not_empty);

    pthread_mutex_unlock(&pool->mutex);

    // Join all worker threads
    for (int i = 0; i < pool->num_workers; i++) {
        pthread_join(pool->workers[i], NULL);
    }

    // Cleanup
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->not_empty);
    pthread_cond_destroy(&pool->all_done);

    free(pool->workers);
    free(pool);
}

/* ======================== EXAMPLE USAGE ======================== */

// Example task function
void example_task(void* arg) {
    int task_id = *(int*)arg;
    printf("Task %d started by thread %lu\n", task_id, (unsigned long)pthread_self());
    sleep(1);  // Simulate work
    printf("Task %d completed\n", task_id);
    free(arg);  // Free the argument we allocated
}

int main() {
    // Create a thread pool with 4 workers
    thread_pool_t* pool = thread_pool_create(4);
    if (!pool) {
        fprintf(stderr, "Failed to create thread pool\n");
        return 1;
    }

    printf("Thread pool created with 4 workers\n");

    // Submit 10 tasks
    for (int i = 0; i < 10; i++) {
        int* task_arg = malloc(sizeof(int));
        *task_arg = i;

        if (!thread_pool_submit(pool, example_task, task_arg)) {
            fprintf(stderr, "Failed to submit task %d\n", i);
            free(task_arg);
        }
    }

    printf("All tasks submitted\n");

    // Shutdown pool and wait for all tasks to complete
    printf("Shutting down thread pool and waiting for tasks...\n");
    thread_pool_shutdown(pool, true);

    printf("Thread pool shutdown complete\n");
    return 0;
}
```

## Compilation and Usage

To compile:
```bash
gcc -pthread -o threadpool threadpool.c
```

To run:
```bash
./threadpool
```

## Key Features

1. **Fixed Worker Threads**: Creates a fixed number of worker threads at initialization.

2. **Task Queue with Mutex+Condvar**:
   - `pthread_mutex_t mutex` protects access to the task queue
   - `pthread_cond_t not_empty` signals when tasks are available
   - `pthread_cond_t all_done` signals when all tasks complete (for shutdown)

3. **Task Submission**: `thread_pool_submit()` safely adds tasks to the queue.

4. **Graceful Shutdown**: 
   - `thread_pool_shutdown(pool, true)` waits for all tasks to complete
   - `thread_pool_shutdown(pool, false)` aborts remaining tasks

5. **Dynamic Task Allocation**: Tasks are allocated and freed properly to avoid memory leaks.

## How It Works

1. **Workers** wait on the `not_empty` condition when the queue is empty
2. When a task is submitted, it's added to the queue and `not_empty` is signaled
3. A worker dequeues the task, executes it, and frees the task structure
4. On shutdown, the shutdown flag is set, workers are woken, and they exit when no tasks remain
5. The main thread joins all workers before cleanup

This skeleton provides a solid foundation that can be extended with features like dynamic pool resizing, task priorities, or result collection.

# Memory Leak Detector in C

Here's a well-documented implementation that processes a log of `malloc`/`free` events and reports any pointers that were never freed.

## The Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ──────────────────────────── Types ──────────────────────────── */

typedef enum {
    EVENT_MALLOC,
    EVENT_FREE
} EventType;

typedef struct {
    void       *ptr;     /* pointer from the event                */
    EventType   event;   /* what happened to it                   */
    int         line;    /* source line (optional, for reporting) */
} LogEntry;

/* Internal bookkeeping: one record per unique pointer */
typedef struct {
    void  *ptr;
    int    alloc_count;   /* how many times malloc logged         */
    int    free_count;    /* how many times free   logged         */
    int    first_line;    /* line of first malloc (for context)   */
} PointerRecord;

/* Result: a leaked pointer + context */
typedef struct {
    void  *ptr;
    int    alloc_count;
    int    free_count;
    int    first_line;
} LeakReport;

/* ──────────────────────── Core Logic ─────────────────────────── */

/*
 * detect_leaks
 *
 * Scans `log` of `log_len` entries and writes up to `max_report`
 * leaked pointer records into `reports`.  Returns the number of
 * leaks actually found.
 */
int detect_leaks(const LogEntry  *log,
                 int              log_len,
                 LeakReport      *reports,
                 int              max_report)
{
    /* -----------------------------------------------------------
     * 1.  Build a table of unique pointers.
     *     For small / medium logs a simple dynamic array works.
     *     (Production code would use a hash set.)
     * --------------------------------------------------------- */
    PointerRecord *table = NULL;
    int table_len = 0;
    int table_cap = 0;

    for (int i = 0; i < log_len; i++) {

        /* --- check if pointer is already in the table --- */
        int found = -1;
        for (int j = 0; j < table_len; j++) {
            if (table[j].ptr == log[i].ptr) {
                found = j;
                break;
            }
        }

        /* --- add a new slot if needed --- */
        if (found == -1) {
            if (table_len == table_cap) {
                table_cap = table_cap ? table_cap * 2 : 16;
                table = realloc(table, table_cap * sizeof *table);
                if (!table) {
                    perror("realloc");
                    return -1;
                }
            }
            found = table_len++;
            table[found].ptr         = log[i].ptr;
            table[found].alloc_count = 0;
            table[found].free_count  = 0;
            table[found].first_line  = log[i].line;
        }

        /* --- update counters --- */
        switch (log[i].event) {
            case EVENT_MALLOC:
                table[found].alloc_count++;
                break;
            case EVENT_FREE:
                table[found].free_count++;
                break;
        }
    }

    /* -----------------------------------------------------------
     * 2.  A pointer is "leaked" if alloc_count > free_count.
     *     Collect them into the output buffer.
     * --------------------------------------------------------- */
    int leaks = 0;
    for (int j = 0; j < table_len; j++) {
        if (table[j].alloc_count > table[j].free_count) {
            if (leaks < max_report) {
                reports[leaks].ptr         = table[j].ptr;
                reports[leaks].alloc_count = table[j].alloc_count;
                reports[leaks].free_count  = table[j].free_count;
                reports[leaks].first_line  = table[j].first_line;
            }
            leaks++;
        }
    }

    free(table);
    return leaks;
}

/* ──────────────────────── Pretty Print ───────────────────────── */

static void print_report(const LeakReport *r, int count)
{
    if (count == 0) {
        printf("✅ No memory leaks detected.\n");
        return;
    }
    printf("❌ %d leak(s) detected:\n", count);
    for (int i = 0; i < count; i++) {
        printf("   Pointer %p  (malloc'd %d time(s), freed %d time(s))",
               r[i].ptr, r[i].alloc_count, r[i].free_count);
        if (r[i].first_line)
            printf("  [first seen at line %d]", r[i].first_line);
        printf("\n");
    }
}

/* ──────────────────────── Demo / main ────────────────────────── */

int main(void)
{
    /* Simulated log: three pointers, one leaked */
    LogEntry log[] = {
        { (void *)0x1000, EVENT_MALLOC, 10 },
        { (void *)0x2000, EVENT_MALLOC, 15 },
        { (void *)0x1000, EVENT_FREE,   20 },   /* 0x1000 freed ✓ */
        { (void *)0x3000, EVENT_MALLOC, 25 },
        { (void *)0x2000, EVENT_FREE,   30 },   /* 0x2000 freed ✓ */
        /* 0x3000 never freed — LEAK */
    };
    int log_len = sizeof log / sizeof log[0];

    LeakReport reports[64];
    int leaks = detect_leaks(log, log_len, reports, 64);

    print_report(reports, leaks);

    return 0;
}
```

## Expected Output

```
❌ 1 leak(s) detected:
   Pointer 0x3000  (malloc'd 1 time(s), freed 0 time(s))  [first seen at line 25]
```

## How It Works (Visual Walkthrough)

```
Log Entry              0x1000         0x2000         0x3000
─────────────────────────────────────────────────────────────
malloc (line 10)       alloc=1
malloc (line 15)                        alloc=1
free   (line 20)       alloc=1,free=1
malloc (line 25)                                            alloc=1
free   (line 30)                        alloc=1,free=1
─────────────────────────────────────────────────────────────
Final check             freed ✓         freed ✓        LEAK ✗
```

## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`alloc_count > free_count`** | Tolerates duplicate/mismatched logs gracefully |
| **Dynamic array for tracking** | Simple, no external deps; swap in a hash map for large logs |
| **`LeakReport` output struct** | Keeps the API clean — caller decides how to display |
