# C Dynamic Array (Vector) for Integers

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

/* ------------------------------------------------------------------ */
/*  Vector struct                                                      */
/* ------------------------------------------------------------------ */
typedef struct {
    int   *data;       /* heap-allocated buffer                       */
    size_t size;       /* number of elements currently stored         */
    size_t capacity;   /* number of elements that fit before realloc  */
} Vector;

/* Default initial capacity (must be > 0).                            */
#define VEC_INIT_CAP 16

/* Geometric growth factor — doubling gives amortised O(1) push.      */
#define GROW_FACTOR 2

/* ------------------------------------------------------------------ */
/*  Internal helpers                                                   */
/* ------------------------------------------------------------------ */

/* Abort-friendly wrapper around malloc.  Returns NULL only if size
   is 0 (which is a valid edge case we handle gracefully elsewhere).   */
static int *vec__malloc(size_t n)
{
    if (n == 0) return NULL;
    int *p = (int *)malloc(n * sizeof(int));
    if (!p) {
        fprintf(stderr, "vec: malloc failed (%zu bytes)\n",
                n * sizeof(int));
        exit(EXIT_FAILURE);
    }
    return p;
}

static int *vec__realloc(int *old, size_t new_cap)
{
    int *p = (int *)realloc(old, new_cap * sizeof(int));
    if (!p) {
        fprintf(stderr, "vec: realloc failed (%zu bytes)\n",
                new_cap * sizeof(int));
        exit(EXIT_FAILURE);
    }
    return p;
}

/* Ensure capacity >= new_cap.  Geometric growth when growing.         */
static void vec__grow(Vector *v, size_t new_cap)
{
    if (new_cap <= v->capacity)
        return;

    size_t cap = v->capacity ? v->capacity : VEC_INIT_CAP;
    while (cap < new_cap)
        cap *= GROW_FACTOR;

    v->data     = vec__realloc(v->data, cap);
    v->capacity = cap;
}

/* ------------------------------------------------------------------ */
/*  Public API                                                         */
/* ------------------------------------------------------------------ */

/* Create an empty vector with default capacity.                       */
Vector *vec_new(void)
{
    Vector *v = (Vector *)malloc(sizeof(Vector));
    if (!v) {
        fprintf(stderr, "vec: malloc failed (Vector)\n");
        exit(EXIT_FAILURE);
    }
    v->data     = NULL;
    v->size     = 0;
    v->capacity = 0;
    return v;
}

/* Free all memory.                                                    */
void vec_free(Vector *v)
{
    if (!v) return;
    free(v->data);
    free(v);
}

/* Return number of elements.                                          */
size_t vec_size(const Vector *v) { return v->size; }

/* Return current capacity.                                            */
size_t vec_capacity(const Vector *v) { return v->capacity; }

/* Pointer to element at index i (no bounds check — use vec_at).       */
int *vec_get(const Vector *v, size_t i)
{
    assert(i < v->size && "vec_get: index out of bounds");
    return &v->data[i];
}

/* Safe element access (returns NULL on out-of-bounds).                 */
int *vec_at(const Vector *v, size_t i)
{
    return (i < v->size) ? &v->data[i] : NULL;
}

/* Pointer to first element (or NULL if empty).                         */
int *vec_front(const Vector *v) { return v->size ? &v->data[0] : NULL; }

/* Pointer past-the-last element (or NULL if empty).                    */
int *vec_back(const Vector *v) { return v->size ? &v->data[v->size - 1] : NULL; }

/* Raw data pointer (useful for passing to qsort, etc.).                */
int *vec_data(const Vector *v) { return v->data; }

/* ---- Core operations ------------------------------------------------ */

/* Reserve at least `cap` slots.  Never shrinks.                        */
void vec_reserve(Vector *v, size_t cap)
{
    vec__grow(v, cap);
}

/* Push an element to the end — amortised O(1).                         */
void vec_push(Vector *v, int value)
{
    vec__grow(v, v->size + 1);
    v->data[v->size++] = value;
}

/* Pop the last element.  Undefined if empty (use vec_size first).      */
int vec_pop(Vector *v)
{
    assert(v->size > 0 && "vec_pop: vector is empty");
    return v->data[--v->size];
}

/* Remove all elements (capacity unchanged, no deallocation).           */
void vec_clear(Vector *v)
{
    v->size = 0;
}

/* Release unused memory so that capacity == size.                       */
void vec_shrink_to_fit(Vector *v)
{
    if (v->size == 0) {
        free(v->data);
        v->data     = NULL;
        v->capacity = 0;
        return;
    }
    int *p = vec__realloc(v->data, v->size);   /* realloc down */
    v->data     = p;
    v->capacity = v->size;
}

/* ------------------------------------------------------------------ */
/*  Demo / self-test                                                   */
/* ------------------------------------------------------------------ */
int main(void)
{
    Vector *v = vec_new();

    /* Push 1 000 elements — capacity will grow geometrically. */
    printf("Pushing 1000 elements …\n");
    for (int i = 0; i < 1000; i++)
        vec_push(v, i);

    printf("  size     = %zu\n", vec_size(v));
    printf("  capacity = %zu  (geometric growth from %d)\n",
           vec_capacity(v), VEC_INIT_CAP);
    assert(vec_size(v) == 1000);

    /* Peek at a few elements. */
    printf("  v[0]   = %d\n", *vec_get(v, 0));
    printf("  v[999] = %d\n", *vec_get(v, 999));

    /* Pop all. */
    printf("Popping all 1000 elements …\n");
    for (int i = 999; i >= 0; i--) {
        int x = vec_pop(v);
        assert(x == i);
    }
    printf("  size after pops = %zu\n", vec_size(v));
    printf("  capacity unchanged = %zu\n", vec_capacity(v));

    /* shrink_to_fit should release everything (size == 0). */
    vec_shrink_to_fit(v);
    printf("After shrink_to_fit: capacity = %zu\n", vec_capacity(v));
    assert(vec_capacity(v) == 0);

    /* Push a few more, then shrink. */
    for (int i = 0; i < 5; i++)
        vec_push(v, i * 10);
    printf("  size=%zu  capacity=%zu\n", vec_size(v), vec_capacity(v));

    vec_shrink_to_fit(v);
    printf("After shrink_to_fit: size=%zu  capacity=%zu\n",
           vec_size(v), vec_capacity(v));
    assert(vec_capacity(v) == vec_size(v));

    /* Demonstrate reserve. */
    vec_reserve(v, 256);
    printf("After reserve(256): size=%zu  capacity=%zu\n",
           vec_size(v), vec_capacity(v));
    assert(vec_capacity(v) >= 256);

    vec_free(v);
    printf("\nAll tests passed.\n");
    return 0;
}
```

## Design Notes

| Aspect | Detail |
|---|---|
| **Amortised O(1) push** | Capacity doubles each time (`GROW_FACTOR 2`). The classic accounting argument: each element pays for its own copy *plus* one future copy, so the average cost per push is constant. |
| **`vec_reserve`** | Pre-allocates to avoid repeated reallocations when you know the final size. Never shrinks. |
| **`vec_shrink_to_fit`** | `realloc`s the buffer down to exactly `size` (or frees it entirely if empty), reclaiming wasted memory. |
| **`vec_pop`** | Returns the value and decrements `size`; does **not** free/realloc the buffer. |
| **`vec_at` vs `vec_get`** | `vec_at` returns `NULL` on out-of-bounds (safe); `vec_get` asserts (fast, debug-friendly). |
| **Growth strategy** | Geometric doubling is the standard trick — it guarantees each old element is copied at most *O(log n)* times total across *n* pushes, giving the amortised bound. |

```c
#include <math.h>
#include <float.h>

/**
 * Computes softmax in-place over a float array in a numerically stable way.
 *
 * For each element:  x[i] = exp(x[i] - max) / sum(exp(x[j] - max))
 *
 * Subtracting the maximum before exponentiation prevents overflow.
 */
void softmax(float *arr, int n)
{
    if (n <= 0) return;

    /* 1. Find the maximum value */
    float max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }

    /* 2. Compute exp(x[i] - max) in place and accumulate the sum */
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        arr[i] = expf(arr[i] - max);
        sum += arr[i];
    }

    /* 3. Normalize */
    for (int i = 0; i < n; i++) {
        arr[i] /= sum;
    }
}
```

### How it works

| Step | Purpose |
|---|---|
| **Find max** | Shifts every value so the largest is 0. This keeps all `exp()` inputs ≤ 0, eliminating overflow. |
| **exp(x − max)** | Evaluates the exponentials in-place; the sum of results accumulates in `sum`. |
| **Divide by sum** | Normalizes so the array sums to exactly 1. |

### Why subtracting the max is enough

- `exp(x − max)` never exceeds `exp(0) = 1`, so **no overflow**.
- For values far below the max the result is near 0 — harmless underflow that doesn't affect the result.
- The constant offset cancels out in the division: `exp(x)/Σexp(x) = exp(x−c)/Σexp(x−c)`.

