Here's a C function that tokenizes a string by whitespace without modifying the input, with proper memory management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Tokenizes a string by whitespace without modifying the input.
 * 
 * @param input     The input string to tokenize
 * @param count     Output parameter: number of tokens found
 * @return          Array of token strings (caller must free with tokenize_cleanup)
 */
char** tokenize(const char* input, int* count) {
    if (!input || !count) {
        if (count) *count = 0;
        return NULL;
    }

    *count = 0;

    // Skip leading whitespace
    const char* ptr = input;
    while (*ptr && isspace((unsigned char)*ptr)) {
        ptr++;
    }

    if (*ptr == '\0') {
        return NULL;  // Empty string or only whitespace
    }

    // Count tokens
    int token_count = 0;
    const char* current = ptr;
    while (*current) {
        // Skip non-whitespace characters
        while (*current && !isspace((unsigned char)*current)) {
            current++;
        }
        token_count++;

        // Skip whitespace characters
        while (*current && isspace((unsigned char)*current)) {
            current++;
        }
    }

    // Allocate array of token pointers
    char** tokens = (char**)malloc((token_count + 1) * sizeof(char*));
    if (!tokens) {
        *count = 0;
        return NULL;
    }

    // Extract tokens
    int idx = 0;
    current = ptr;
    while (*current && idx < token_count) {
        // Find start of token
        while (*current && isspace((unsigned char)*current)) {
            current++;
        }

        if (*current == '\0') {
            break;
        }

        // Find end of token
        const char* token_start = current;
        while (*current && !isspace((unsigned char)*current)) {
            current++;
        }

        // Calculate token length
        size_t token_len = current - token_start;

        // Allocate and copy token
        tokens[idx] = (char*)malloc((token_len + 1) * sizeof(char));
        if (!tokens[idx]) {
            // Cleanup already allocated tokens on failure
            for (int i = 0; i < idx; i++) {
                free(tokens[i]);
            }
            free(tokens);
            *count = 0;
            return NULL;
        }

        memcpy(tokens[idx], token_start, token_len);
        tokens[idx][token_len] = '\0';
        idx++;
    }

    tokens[idx] = NULL;  // NULL-terminate the array
    *count = idx;
    return tokens;
}

/**
 * Frees memory allocated by tokenize().
 * 
 * @param tokens    Array of tokens to free
 */
void tokenize_cleanup(char** tokens) {
    if (!tokens) {
        return;
    }

    // Free each token string
    for (int i = 0; tokens[i] != NULL; i++) {
        free(tokens[i]);
    }

    // Free the array itself
    free(tokens);
}

// Example usage
int main() {
    const char* text = "  Hello   world!  This is a test.  ";
    int token_count = 0;

    char** tokens = tokenize(text, &token_count);

    if (tokens) {
        printf("Found %d tokens:\n", token_count);
        for (int i = 0; i < token_count; i++) {
            printf("  %d: \"%s\"\n", i + 1, tokens[i]);
        }

        // Clean up memory
        tokenize_cleanup(tokens);
    } else {
        printf("No tokens found.\n");
    }

    return 0;
}
```

## Key Features:

1. **Non-destructive**: Doesn't modify the original input string
2. **Whitespace handling**: Treats any sequence of whitespace (spaces, tabs, newlines) as delimiters
3. **Proper memory management**: 
   - Returns a NULL-terminated array of strings
   - Provides `tokenize_cleanup()` function for proper deallocation
   - Handles allocation failures gracefully with cleanup

## Design Decisions:

1. **Two-pass approach**: First counts tokens to allocate exact memory, then extracts tokens
2. **Safe memory handling**: Uses `memcpy` instead of `strcpy` for security
3. **NULL-termination**: Both the array and individual tokens are properly NULL-terminated
4. **Error handling**: Properly cleans up memory on allocation failures
5. **Whitespace detection**: Uses `isspace()` from `<ctype.h>` for locale-aware whitespace detection

## Usage:

```c
// Tokenize a string
int count;
char** tokens = tokenize("Hello world", &count);

// Use tokens...
for (int i = 0; i < count; i++) {
    printf("Token %d: %s\n", i, tokens[i]);
}

// Always clean up when done
tokenize_cleanup(tokens);
```

The function returns an array that can be safely iterated up to `count` elements, with `tokens[count]` being NULL.

Here's a C implementation for a binary file header with endianness checks and error reporting:

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

// Define the file magic number
#define FILE_MAGIC 0x4D494D4F // "MIMO" in ASCII

// Header structure (without packing)
#pragma pack(push, 1)
typedef struct {
    uint32_t magic;    // Magic number for validation
    uint32_t version;  // File format version
    uint64_t count;    // Number of records
} BinFileHeader;
#pragma pack(pop)

// Error codes for the parser
typedef enum {
    PARSE_SUCCESS = 0,
    PARSE_ERROR_FILE_NOT_FOUND,
    PARSE_ERROR_READ_FAILED,
    PARSE_ERROR_MAGIC_MISMATCH,
    PARSE_ERROR_INVALID_VERSION,
    PARSE_ERROR_ENDIANNESS_MISMATCH
} ParseResult;

// Function to check if system is little-endian
static int is_system_little_endian() {
    uint32_t test = 1;
    return *(uint8_t*)&test == 1;
}

// Byte swapping functions
static uint32_t swap_uint32(uint32_t val) {
    return ((val & 0xFF) << 24) |
           ((val & 0xFF00) << 8) |
           ((val >> 8) & 0xFF00) |
           ((val >> 24) & 0xFF);
}

static uint64_t swap_uint64(uint64_t val) {
    return ((val & 0x00000000000000FFULL) << 56) |
           ((val & 0x000000000000FF00ULL) << 40) |
           ((val & 0x0000000000FF0000ULL) << 24) |
           ((val & 0x00000000FF000000ULL) << 8)  |
           ((val & 0x000000FF00000000ULL) >> 8)  |
           ((val & 0x0000FF0000000000ULL) >> 24) |
           ((val & 0x00FF000000000000ULL) >> 40) |
           ((val & 0xFF00000000000000ULL) >> 56);
}

// Parse binary header from file
ParseResult parse_binary_header(const char *filename, BinFileHeader *header, int target_little_endian) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return PARSE_ERROR_FILE_NOT_FOUND;
    }

    // Read the header bytes
    size_t bytes_read = fread(header, sizeof(BinFileHeader), 1, file);
    fclose(file);

    if (bytes_read != 1) {
        return PARSE_ERROR_READ_FAILED;
    }

    // Determine endianness of file vs system
    int system_le = is_system_little_endian();
    int need_swap = (system_le != target_little_endian);

    // Convert if needed
    if (need_swap) {
        header->magic = swap_uint32(header->magic);
        header->version = swap_uint32(header->version);
        header->count = swap_uint64(header->count);
    }

    // Validate magic number
    if (header->magic != FILE_MAGIC) {
        return PARSE_ERROR_MAGIC_MISMATCH;
    }

    // Validate version (assuming max version 100 for this example)
    if (header->version > 100) {
        return PARSE_ERROR_INVALID_VERSION;
    }

    return PARSE_SUCCESS;
}

// Helper function to get error message
const char* get_parse_error_message(ParseResult result) {
    switch (result) {
        case PARSE_SUCCESS:
            return "Success";
        case PARSE_ERROR_FILE_NOT_FOUND:
            return "File not found";
        case PARSE_ERROR_READ_FAILED:
            return "Failed to read header";
        case PARSE_ERROR_MAGIC_MISMATCH:
            return "Magic number mismatch";
        case PARSE_ERROR_INVALID_VERSION:
            return "Invalid version number";
        case PARSE_ERROR_ENDIANNESS_MISMATCH:
            return "Endianness mismatch";
        default:
            return "Unknown error";
    }
}

// Example usage
int main() {
    BinFileHeader header;

    // Try to parse a binary file
    ParseResult result = parse_binary_header("test.bin", &header, 1); // 1 for little-endian

    if (result == PARSE_SUCCESS) {
        printf("Header parsed successfully:\n");
        printf("Magic: 0x%08X\n", header.magic);
        printf("Version: %u\n", header.version);
        printf("Count: %lu\n", (unsigned long)header.count);
    } else {
        printf("Error: %s\n", get_parse_error_message(result));
    }

    return 0;
}
```

Key features of this implementation:

1. **Struct Definition**: 
   - Uses `#pragma pack` to ensure no padding between fields
   - Fields are properly sized using `uint32_t` and `uint64_t`
   - Clear documentation of each field

2. **Endianness Handling**:
   - Detects system endianness at runtime
   - Supports both little-endian and big-endian file formats
   - Provides byte-swapping functions for conversion
   - Parameter to specify target endianness of the file

3. **Error Reporting**:
   - Comprehensive error codes covering common failure scenarios
   - Clear error messages for debugging
   - Specific validation for magic number and version

4. **Robust Parsing**:
   - File handling with proper error checking
   - Validation of magic number for format verification
   - Version checking (with customizable limits)
   - Complete error handling for all operations

5. **Portability**:
   - Standard C libraries only
   - Works on both 32-bit and 64-bit systems
   - Compatible with any platform regardless of endianness

