Here's a C function that handles both UTF-8 to UTF-32 decoding and UTF-32 to UTF-8 encoding, with proper validation of invalid sequences:

```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

// Error code returned for invalid sequences
#define UTF_ERROR_INVALID_SEQUENCE 0xFFFFFFFF

// Maximum valid Unicode codepoint
#define UTF_MAX_CODEPOINT 0x10FFFF

/**
 * Decode a UTF-8 sequence to a UTF-32 codepoint
 * 
 * @param utf8 Input UTF-8 string
 * @param length Input string length (in bytes)
 * @param bytes_consumed Output: number of bytes consumed from input
 * @return The decoded codepoint, or UTF_ERROR_INVALID_SEQUENCE on error
 */
uint32_t utf8_to_utf32(const uint8_t* utf8, size_t length, size_t* bytes_consumed)
{
    if (!utf8 || !bytes_consumed || length == 0) {
        if (bytes_consumed) *bytes_consumed = 0;
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    *bytes_consumed = 0;
    uint32_t codepoint;
    uint8_t first_byte = utf8[0];
    size_t expected_bytes;

    // Determine expected number of bytes based on first byte
    if (first_byte < 0x80) {
        // ASCII (0xxxxxxx)
        codepoint = first_byte;
        expected_bytes = 1;
    } else if ((first_byte & 0xE0) == 0xC0) {
        // 2-byte sequence (110xxxxx)
        codepoint = first_byte & 0x1F;
        expected_bytes = 2;
    } else if ((first_byte & 0xF0) == 0xE0) {
        // 3-byte sequence (1110xxxx)
        codepoint = first_byte & 0x0F;
        expected_bytes = 3;
    } else if ((first_byte & 0xF8) == 0xF0) {
        // 4-byte sequence (11110xxx)
        codepoint = first_byte & 0x07;
        expected_bytes = 4;
    } else {
        // Invalid continuation byte or invalid start byte (10xxxxxx or 11111xxx)
        *bytes_consumed = 1;
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    // Check if we have enough bytes
    if (length < expected_bytes) {
        *bytes_consumed = length;
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    // Process continuation bytes
    for (size_t i = 1; i < expected_bytes; i++) {
        uint8_t byte = utf8[i];
        if ((byte & 0xC0) != 0x80) {
            // Invalid continuation byte
            *bytes_consumed = i;
            return UTF_ERROR_INVALID_SEQUENCE;
        }
        codepoint = (codepoint << 6) | (byte & 0x3F);
    }

    *bytes_consumed = expected_bytes;

    // Validate the decoded codepoint
    // 1. Check for overlong sequences
    if (expected_bytes == 2 && codepoint < 0x80) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }
    if (expected_bytes == 3 && codepoint < 0x800) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }
    if (expected_bytes == 4 && codepoint < 0x10000) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    // 2. Check for surrogate halves (U+D800 to U+DFFF)
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    // 3. Check for codepoints above Unicode maximum
    if (codepoint > UTF_MAX_CODEPOINT) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    // 4. Check for invalid UTF-32 values
    if (codepoint == 0xFFFE || codepoint == 0xFFFF) {
        return UTF_ERROR_INVALID_SEQUENCE;
    }

    return codepoint;
}

/**
 * Encode a UTF-32 codepoint to UTF-8
 * 
 * @param codepoint Input UTF-32 codepoint
 * @param utf8 Output UTF-8 buffer
 * @param max_length Maximum bytes in output buffer
 * @return Number of bytes written, or 0 on error
 */
size_t utf32_to_utf8(uint32_t codepoint, uint8_t* utf8, size_t max_length)
{
    if (!utf8 || max_length == 0) {
        return 0;
    }

    // Validate codepoint
    if (codepoint > UTF_MAX_CODEPOINT || 
        (codepoint >= 0xD800 && codepoint <= 0xDFFF) ||
        codepoint == 0xFFFE || codepoint == 0xFFFF) {
        return 0;
    }

    size_t bytes_needed;

    // Determine how many bytes we need
    if (codepoint < 0x80) {
        bytes_needed = 1;
    } else if (codepoint < 0x800) {
        bytes_needed = 2;
    } else if (codepoint < 0x10000) {
        bytes_needed = 3;
    } else {
        bytes_needed = 4;
    }

    // Check if buffer is large enough
    if (max_length < bytes_needed) {
        return 0;
    }

    // Encode the codepoint
    switch (bytes_needed) {
        case 1:
            utf8[0] = (uint8_t)codepoint;
            break;
        case 2:
            utf8[0] = (uint8_t)(0xC0 | (codepoint >> 6));
            utf8[1] = (uint8_t)(0x80 | (codepoint & 0x3F));
            break;
        case 3:
            utf8[0] = (uint8_t)(0xE0 | (codepoint >> 12));
            utf8[1] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
            utf8[2] = (uint8_t)(0x80 | (codepoint & 0x3F));
            break;
        case 4:
            utf8[0] = (uint8_t)(0xF0 | (codepoint >> 18));
            utf8[1] = (uint8_t)(0x80 | ((codepoint >> 12) & 0x3F));
            utf8[2] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
            utf8[3] = (uint8_t)(0x80 | (codepoint & 0x3F));
            break;
    }

    return bytes_needed;
}
```

## Key Features:

### UTF-8 to UTF-32 (Decoding):
1. **Handles variable-length sequences** (1-4 bytes)
2. **Validates continuation bytes** (10xxxxxx pattern)
3. **Detects and rejects**:
   - Overlong sequences
   - Surrogate halves (U+D800-U+DFFF)
   - Codepoints above U+10FFFF
   - Invalid UTF-32 values (U+FFFE, U+FFFF)
4. **Reports bytes consumed** for partial sequences
5. **Returns `UTF_ERROR_INVALID_SEQUENCE`** for invalid input

### UTF-32 to UTF-8 (Encoding):
1. **Validates input codepoints** before encoding
2. **Generates correct UTF-8 sequences** for all valid codepoints
3. **Returns 0 bytes written** for invalid codepoints
4. **Checks buffer size** to prevent overflow
5. **Handles all Unicode ranges** from ASCII to supplementary characters

## Usage Example:
```c
#include <stdio.h>

int main() {
    // Example: Decode "你好" (U+4F60, U+597D)
    const uint8_t hello_utf8[] = {0xE4, 0xBD, 0xA0, 0xE5, 0xA5, 0xBD, 0x00};
    size_t consumed;

    size_t i = 0;
    while (hello_utf8[i] != 0) {
        uint32_t cp = utf8_to_utf32(&hello_utf8[i], 4, &consumed);
        if (cp == UTF_ERROR_INVALID_SEQUENCE) {
            printf("Invalid sequence at position %zu\n", i);
            break;
        }
        printf("Codepoint: U+%04X (%c)\n", cp, cp);
        i += consumed;
    }

    // Example: Encode U+1F600 (😀)
    uint8_t emoji[4];
    size_t bytes = utf32_to_utf8(0x1F600, emoji, sizeof(emoji));
    printf("Emoji encoded to %zu bytes\n", bytes);

    return 0;
}
```

