#include <stdint.h>
#include <stddef.h>

// Error codes
#define READ_OK           0
#define READ_ERR_BOUNDS   1
#define READ_ERR_VARINT   2

/**
 * Reads a little-endian uint64 and a varint from a byte buffer.
 * 
 * @param buf      Pointer to the start of the byte buffer
 * @param buf_size Size of the buffer in bytes
 * @param pos      Pointer to current position (will be updated)
 * @param out_u64  Output variable for the uint64 value
 * @param out_var  Output variable for the varint value
 * @return READ_OK on success, error code on failure
 */
int read_uint64_varint(const uint8_t *buf, size_t buf_size, size_t *pos, 
                       uint64_t *out_u64, uint64_t *out_var)
{
    if (!buf || !pos || !out_u64 || !out_var)
        return READ_ERR_BOUNDS;

    // Check if we have enough bytes for uint64 (8 bytes)
    if (*pos + 8 > buf_size)
        return READ_ERR_BOUNDS;

    // Read little-endian uint64
    const uint8_t *u64_bytes = buf + *pos;
    *out_u64 = 0;
    for (int i = 0; i < 8; i++) {
        *out_u64 |= ((uint64_t)u64_bytes[i]) << (i * 8);
    }
    *pos += 8;

    // Read varint with bounds checking
    *out_var = 0;
    int shift = 0;
    uint8_t byte;

    do {
        // Check bounds
        if (*pos >= buf_size)
            return READ_ERR_VARINT;

        byte = buf[*pos];
        (*pos)++;

        // Check for overflow (varint too long)
        if (shift >= 64)
            return READ_ERR_VARINT;

        // Extract lower 7 bits and add to result
        *out_var |= ((uint64_t)(byte & 0x7F)) << shift;
        shift += 7;

    } while (byte & 0x80);  // Continue while high bit is set

    return READ_OK;
}
```

## Key Features:

1. **Bounds Checking**: 
   - Verifies there are at least 8 bytes for the uint64
   - Checks buffer bounds for each varint byte
   - Prevents reading beyond buffer end

2. **Little-endian uint64**: 
   - Reads 8 bytes and reconstructs the uint64 value by shifting each byte into its correct position (byte 0 is LSB)

3. **Varint Decoding**:
   - Uses standard Protocol Buffers varint encoding
   - Each byte contributes 7 bits, high bit indicates continuation
   - Maximum 10 bytes for 64-bit values
   - Prevents overflow (shift ≥ 64)

4. **Cursor Advancement**:
   - Updates `pos` after successful reads
   - Leaves `pos` unchanged on error (except partial varint reads)

