```c
int main() {
    uint8_t buffer[] = {
        // Little-endian uint64: 0x0123456789ABCDEF
        0xEF, 0xCD, 0xAB, 0x89, 0x67, 0x45, 0x23, 0x01,
        // Varint: 300 (encoded as 0xAC, 0x02)
        0xAC, 0x02
    };

    size_t pos = 0;
    uint64_t u64_val, varint_val;

    int result = read_uint64_varint(buffer, sizeof(buffer), &pos, 
                                   &u64_val, &varint_val);

