Here's a minimal JSON tokenizer in C that produces an array of tokens with type, start, and length:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* Token types */
typedef enum {
    TOKEN_LBRACE,      // {
    TOKEN_RBRACE,      // }
    TOKEN_LBRACKET,    // [
    TOKEN_RBRACKET,    // ]
    TOKEN_COLON,       // :
    TOKEN_COMMA,       // ,
    TOKEN_TRUE,        // true
    TOKEN_FALSE,       // false
    TOKEN_NULL,        // null
    TOKEN_NUMBER,      // numbers
    TOKEN_STRING,      // strings
    TOKEN_ERROR,       // error
    TOKEN_END          // end of input
} Token_type;

/* Token structure */
typedef struct {
    Token_type type;
    int start;
    int length;
} Token;

/* Tokenizer state */
typedef struct {
    const char* input;
    int position;
    int length;
} Tokenizer;

/* Initialize tokenizer */
void tokenizer_init(Tokenizer* tokenizer, const char* input) {
    tokenizer->input = input;
    tokenizer->position = 0;
    tokenizer->length = strlen(input);
}

/* Skip whitespace */
void skip_whitespace(Tokenizer* tokenizer) {
    while (tokenizer->position < tokenizer->length && 
           isspace(tokenizer->input[tokenizer->position])) {
        tokenizer->position++;
    }
}

/* Get next token */
Token get_next_token(Tokenizer* tokenizer) {
    Token token;
    skip_whitespace(tokenizer);

    token.start = tokenizer->position;

    if (tokenizer->position >= tokenizer->length) {
        token.type = TOKEN_END;
        token.length = 0;
        return token;
    }

    char c = tokenizer->input[tokenizer->position];

    /* Single character tokens */
    if (c == '{') {
        token.type = TOKEN_LBRACE;
        token.length = 1;
        tokenizer->position++;
    } else if (c == '}') {
        token.type = TOKEN_RBRACE;
        token.length = 1;
        tokenizer->position++;
    } else if (c == '[') {
        token.type = TOKEN_LBRACKET;
        token.length = 1;
        tokenizer->position++;
    } else if (c == ']') {
        token.type = TOKEN_RBRACKET;
        token.length = 1;
        tokenizer->position++;
    } else if (c == ':') {
        token.type = TOKEN_COLON;
        token.length = 1;
        tokenizer->position++;
    } else if (c == ',') {
        token.type = TOKEN_COMMA;
        token.length = 1;
        tokenizer->position++;
    } 
    /* String tokens */
    else if (c == '"') {
        token.type = TOKEN_STRING;
        tokenizer->position++;  /* Skip opening quote */

        while (tokenizer->position < tokenizer->length && 
               tokenizer->input[tokenizer->position] != '"') {
            if (tokenizer->input[tokenizer->position] == '\\') {
                tokenizer->position++;  /* Skip escaped character */
            }
            tokenizer->position++;
        }

        if (tokenizer->position < tokenizer->length) {
            tokenizer->position++;  /* Skip closing quote */
        }

        token.length = tokenizer->position - token.start;
    } 
    /* Number tokens */
    else if (isdigit(c) || c == '-' || c == '+') {
        token.type = TOKEN_NUMBER;

        /* Handle optional sign */
        if (c == '-' || c == '+') {
            tokenizer->position++;
        }

        /* Integer part */
        while (tokenizer->position < tokenizer->length && 
               isdigit(tokenizer->input[tokenizer->position])) {
            tokenizer->position++;
        }

        /* Decimal part */
        if (tokenizer->position < tokenizer->length && 
            tokenizer->input[tokenizer->position] == '.') {
            tokenizer->position++;
            while (tokenizer->position < tokenizer->length && 
                   isdigit(tokenizer->input[tokenizer->position])) {
                tokenizer->position++;
            }
        }

        /* Exponent part */
        if (tokenizer->position < tokenizer->length && 
            (tokenizer->input[tokenizer->position] == 'e' || 
             tokenizer->input[tokenizer->position] == 'E')) {
            tokenizer->position++;

            if (tokenizer->position < tokenizer->length && 
                (tokenizer->input[tokenizer->position] == '+' || 
                 tokenizer->input[tokenizer->position] == '-')) {
                tokenizer->position++;
            }

            while (tokenizer->position < tokenizer->length && 
                   isdigit(tokenizer->input[tokenizer->position])) {
                tokenizer->position++;
            }
        }

        token.length = tokenizer->position - token.start;
    } 
    /* Keywords */
    else if (isalpha(c)) {
        /* Check for true, false, null */
        if (strncmp(tokenizer->input + tokenizer->position, "true", 4) == 0) {
            token.type = TOKEN_TRUE;
            token.length = 4;
            tokenizer->position += 4;
        } else if (strncmp(tokenizer->input + tokenizer->position, "false", 5) == 0) {
            token.type = TOKEN_FALSE;
            token.length = 5;
            tokenizer->position += 5;
        } else if (strncmp(tokenizer->input + tokenizer->position, "null", 4) == 0) {
            token.type = TOKEN_NULL;
            token.length = 4;
            tokenizer->position += 4;
        } else {
            /* Invalid token */
            token.type = TOKEN_ERROR;
            while (tokenizer->position < tokenizer->length && 
                   isalnum(tokenizer->input[tokenizer->position])) {
                tokenizer->position++;
            }
            token.length = tokenizer->position - token.start;
        }
    } 
    /* Invalid character */
    else {
        token.type = TOKEN_ERROR;
        token.length = 1;
        tokenizer->position++;
    }

    return token;
}

/* Tokenize entire input */
Token* tokenize(const char* input, int* token_count) {
    Tokenizer tokenizer;
    tokenizer_init(&tokenizer, input);

    Token* tokens = NULL;
    int capacity = 0;
    *token_count = 0;

    Token token;
    do {
        token = get_next_token(&tokenizer);

        if (*token_count >= capacity) {
            capacity = capacity == 0 ? 16 : capacity * 2;
            tokens = realloc(tokens, capacity * sizeof(Token));
            if (tokens == NULL) {
                *token_count = 0;
                return NULL;
            }
        }

        tokens[*token_count] = token;
        (*token_count)++;
    } while (token.type != TOKEN_END);

    return tokens;
}

/* Get token type name */
const char* token_type_name(Token_type type) {
    switch (type) {
        case TOKEN_LBRACE:    return "LBRACE";
        case TOKEN_RBRACE:    return "RBRACE";
        case TOKEN_LBRACKET:  return "LBRACKET";
        case TOKEN_RBRACKET:  return "RBRACKET";
        case TOKEN_COLON:     return "COLON";
        case TOKEN_COMMA:     return "COMMA";
        case TOKEN_TRUE:      return "TRUE";
        case TOKEN_FALSE:     return "FALSE";
        case TOKEN_NULL:      return "NULL";
        case TOKEN_NUMBER:    return "NUMBER";
        case TOKEN_STRING:    return "STRING";
        case TOKEN_ERROR:     return "ERROR";
        case TOKEN_END:       return "END";
        default:              return "UNKNOWN";
    }
}

/* Example usage */
int main() {
    const char* json = "{\"name\": \"John\", \"age\": 30, \"active\": true}";

    int token_count;
    Token* tokens = tokenize(json, &token_count);

    if (tokens != NULL) {
        printf("Token count: %d\n", token_count);
        for (int i = 0; i < token_count; i++) {
            printf("Token %d: type=%s, start=%d, length=%d, text=\"%.20s\"\n", 
                   i, 
                   token_type_name(tokens[i].type),
                   tokens[i].start,
                   tokens[i].length,
                   json + tokens[i].start);
        }
        free(tokens);
    } else {
        printf("Tokenization failed\n");
    }

    return 0;
}
```

